INSERT INTO dbo.Quotes (BookId, AuthorId, AddedByUserId, QuoteText, CreatedAt, LikesCount) VALUES
    (8, 4, 52, 'It is a truth universally acknowledged, that a single man in possession of a good fortune, must be in want of a wife.', '2026-07-20', 777),
    (8, 4, 60, 'I could easily forgive his pride, if he had not mortified mine.', '2024-03-18', 848),
    (35, 24, 58, 'It was the best of times, it was the worst of times.', '2022-10-05', 897),
    (28, 19, 23, 'Happy families are all alike; every unhappy family is unhappy in its own way.', '2025-06-27', 298),
    (37, 25, 1, 'Call me Ishmael.', '2024-09-30', 784),
    (33, 22, 60, 'The only way to get rid of a temptation is to yield to it.', '2022-12-07', 702),
    (33, 22, 13, 'There is no such thing as a moral or an immoral book. Books are well written, or badly written.', '2025-04-20', 597),
    (34, 23, 54, 'Curiouser and curiouser!', '2025-09-10', 423),
    (34, 23, 25, 'Why, sometimes I''ve believed as many as six impossible things before breakfast.', '2021-04-29', 636),
    (36, 24, 29, 'Take nothing on its looks; take everything on evidence.', '2022-07-22', 627),
    (30, 20, 80, 'Pain and suffering are always inevitable for a large intelligence and a deep heart.', '2026-08-24', 85),
    (29, 19, 77, N'The strongest of all warriors are these two — Time and Patience.', '2025-08-02', 26),
    (9, 4, 42, 'One half of the world cannot understand the pleasures of the other.', '2023-10-21', 173);
GO

